import{_ as e,c as r,o as a,a3 as o}from"./chunks/framework.BurWKwwG.js";const m=JSON.parse('{"title":"网络分析","description":"","frontmatter":{},"headers":[],"relativePath":"zh/3.5_network.md","filePath":"zh/3.5_network.md"}'),n={name:"zh/3.5_network.md"};function i(s,t,l,d,h,c){return a(),r("div",null,t[0]||(t[0]=[o('<h1 id="网络分析" tabindex="-1">网络分析 <a class="header-anchor" href="#网络分析" aria-label="Permalink to “网络分析”">​</a></h1><p><a href="/network">网络分析</a>页面（<code>/network</code>）提供蛋白质互作（PPI）网络的交互式探索与统计分析，数据来自 <a href="https://string-db.org" target="_blank" rel="noreferrer">STRING</a> 数据库（v12.0），使用 Cytoscape.js 渲染。</p><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to “使用流程”">​</a></h2><ol><li><strong>建网</strong> —— 输入蛋白（或从数据库加载），设置参数后点击 <em>Generate Network</em></li><li><strong>扩展</strong> —— 用高置信度互作伙伴扩展网络</li><li><strong>分析</strong> —— 拓扑、富集、模块、邻近性检验与集合对比</li><li><strong>下载</strong> —— 导出可直接用于发表的图片和完整、可复现的分析包</li></ol><h2 id="构建网络" tabindex="-1">构建网络 <a class="header-anchor" href="#构建网络" aria-label="Permalink to “构建网络”">​</a></h2><h3 id="输入方式" tabindex="-1">输入方式 <a class="header-anchor" href="#输入方式" aria-label="Permalink to “输入方式”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>Manual Input</strong></td><td>每行一个，输入蛋白名称/基因符号</td></tr><tr><td><strong>From Database</strong></td><td>从 CBD 数据库已整理的蛋白中选择</td></tr><tr><td><strong>File Upload</strong></td><td>上传 <code>.txt</code>/<code>.csv</code> 文件（每行一个蛋白）</td></tr></tbody></table><p>建网前会进行 <strong>ID 映射报告</strong>：将输入解析到 STRING，并报告无法匹配的名称。</p><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to “参数”">​</a></h3><ul><li><strong>Species（物种）</strong> —— 支持 STRING 全部 12,000+ 物种（可搜索列表）。本地索引功能（即时扩展、邻近性检验）仅限人类。</li><li><strong>Confidence Score（置信度）</strong> —— 互作纳入的最低 combined score（0–1000）；400 对应中等置信度（STRING 默认）。</li><li><strong>Network Type（网络类型）</strong> —— <em>Functional</em> 汇总全部证据通道；<em>Physical</em> 仅保留直接物理结合。</li><li><strong>Edge Coloring（边配色）</strong> —— <em>Confidence</em>（按 combined score 灰色渐变）或 <em>Evidence</em>（按主导证据通道着色，图上带图例）。</li><li><strong>Hide disconnected nodes</strong> —— 隐藏因过滤而失去所有连边的蛋白。</li></ul><h2 id="网络扩展" tabindex="-1">网络扩展 <a class="header-anchor" href="#网络扩展" aria-label="Permalink to “网络扩展”">​</a></h2><p><em>First-shell Partners</em> 为当前网络中的每个蛋白添加得分最高的 STRING 互作伙伴（每个蛋白 0–20 个）。</p><ul><li><strong>人类</strong>网络使用内置的本地 STRING 索引（combined score ≥ 400）——即时完成，即使服务器无法访问 string-db.org 也可用。</li><li>其他物种通过 STRING API 实时扩展。</li><li>扩展会重新计算统计与拓扑；模块、邻近性与路径结果会因网络变化而重置。可反复应用持续扩大网络。</li></ul><h2 id="可视化" tabindex="-1">可视化 <a class="header-anchor" href="#可视化" aria-label="Permalink to “可视化”">​</a></h2><ul><li><strong>布局</strong> —— 力导向（cose-bilkent）、cose、环形、网格、层级、同心共 6 种布局循环切换；支持缩放与平移。</li><li><strong>证据通道图例</strong> —— 边配色设为 <em>Evidence</em> 时自动显示。</li><li><strong>节点/边对话框</strong> —— 点击节点查看度、中心性、所属模块及懒加载的<strong>功能注释</strong>；点击边查看置信度、主导证据通道及懒加载的<strong>支撑文献</strong>（Europe PMC 共被引检索，链接 PubMed）。</li><li><strong>View in CBD</strong> —— 从网络节点直接跳转到 CBD 数据库中对应的生物标志物条目。</li><li><strong>最短路径搜索</strong> —— 高亮网络中任意两个蛋白之间的连接路径。</li></ul><h3 id="配色方案" tabindex="-1">配色方案 <a class="header-anchor" href="#配色方案" aria-label="Permalink to “配色方案”">​</a></h3><p>默认 <strong>Morandi · Light</strong>（莫兰迪浅色，低饱和灰调），可切换 <strong>Morandi · Classic</strong> 或 <strong>Classic</strong>，也可完全自定义：自行挑选节点颜色与 15 个模块颜色。选择保存在浏览器中并实时生效。模块数超过色板时自动生成互不重复的新颜色。</p><h2 id="分析标签页" tabindex="-1">分析标签页 <a class="header-anchor" href="#分析标签页" aria-label="Permalink to “分析标签页”">​</a></h2><h3 id="topology-拓扑" tabindex="-1">Topology（拓扑） <a class="header-anchor" href="#topology-拓扑" aria-label="Permalink to “Topology（拓扑）”">​</a></h3><p>按蛋白排序的指标表格：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td>Degree</td><td>蛋白在网络内的连接数</td></tr><tr><td>Betweenness</td><td>经过该节点的最短路径数量（桥接/枢纽重要性）</td></tr><tr><td>Closeness</td><td>到其余所有节点平均距离的倒数</td></tr><tr><td>Clustering</td><td>邻居之间互连的程度（1 = 邻居完全互连）</td></tr></tbody></table><p>该标签页还提供<strong>实时边过滤</strong>（低于置信度阈值的边直接隐藏，无需重新请求）和<strong>最短路径搜索</strong>。</p><h3 id="enrichment-富集" tabindex="-1">Enrichment（富集） <a class="header-anchor" href="#enrichment-富集" aria-label="Permalink to “Enrichment（富集）”">​</a></h3><p>由 STRING 计算的过表达分析，按类别分组（GO Process/Function/Component、KEGG、Reactome、WikiPathways、HPO、DISEASES、PMID 等）。列：Term（带链接）、Description、Genes（输入蛋白中命中数）、P-value 与 FDR——判断显著性请以 FDR 为准。</p><h3 id="modules-模块" tabindex="-1">Modules（模块） <a class="header-anchor" href="#modules-模块" aria-label="Permalink to “Modules（模块）”">​</a></h3><p>使用 <strong>Louvain 算法</strong>的社区发现。节点按模块着色；表格报告模块大小、内部连边数与密度，支持在图中<strong>隔离</strong>单个模块或运行<strong>模块级富集</strong>。</p><h3 id="proximity-test-邻近性检验" tabindex="-1">Proximity Test（邻近性检验） <a class="header-anchor" href="#proximity-test-邻近性检验" aria-label="Permalink to “Proximity Test（邻近性检验）”">​</a></h3><p>检验蛋白集是否比随机情况更显著地互连，基于本地人类 STRING 网络（combined score ≥ 400）并进行度匹配随机化：</p><ul><li><strong>Cohesion（凝聚度）</strong> —— 蛋白集内部连边数 vs. 随机集合（主统计量）；报告 z 分数、经验 p 值及置换分布直方图</li><li><strong>Proximity（邻近性）</strong> —— 蛋白集内部平均最短距离 vs. 随机集合（Menche 风格）</li><li>解读：z &gt; 2 且 p &lt; 0.05 表示蛋白集在功能上显著聚集，而非随机组合</li></ul><h3 id="compare-集合对比" tabindex="-1">Compare（集合对比） <a class="header-anchor" href="#compare-集合对比" aria-label="Permalink to “Compare（集合对比）”">​</a></h3><p>输入两个蛋白集（A 与 B）构建并集网络，节点按归属着色——陶土色（仅 A）、蓝灰色（仅 B）、灰紫色（共有）——并给出重叠统计与 <strong>Jaccard 指数</strong> |A∩B| / |A∪B|。</p><h2 id="下载结果" tabindex="-1">下载结果 <a class="header-anchor" href="#下载结果" aria-label="Permalink to “下载结果”">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>内容</th></tr></thead><tbody><tr><td><strong>PNG / SVG</strong></td><td>当前样式（颜色与布局）的网络图片</td></tr><tr><td><strong>GraphML</strong></td><td>可导入 Cytoscape 桌面版的网络文件，含拓扑属性</td></tr><tr><td><strong>Download All</strong></td><td>完整分析包：当前边列表（TSV，含证据通道分数）、富集表（TSV）、模块归属（TSV）、GraphML 文件，以及涵盖所有分析与参数的完整 JSON 快照</td></tr></tbody></table><p>分析包直接从当前内存状态生成——不做任何二次请求——因此下载内容始终与屏幕所见一致。</p><h2 id="实现说明" tabindex="-1">实现说明 <a class="header-anchor" href="#实现说明" aria-label="Permalink to “实现说明”">​</a></h2><ul><li>网络与富集数据经 CBD 后端代理（浏览器不直连 string-db.org）</li><li>本地人类 STRING 索引（combined score ≥ 400，约 1.95 万蛋白 / 46.5 万边）同时支撑 PRS 网络功能</li><li>文献检索由 <a href="https://europepmc.org" target="_blank" rel="noreferrer">Europe PMC</a> 提供</li></ul>',36)]))}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
